diff --git a/snake.c b/snake.c
index 29f85e3..a6f0442 100644
--- a/snake.c
+++ b/snake.c
@@ -86,7 +86,6 @@ void mv_snake(enum dir dir)
 	int x = S.x[S.ihead];

 	/* prevent movement inside oneself */
-	if (S.len > 1) {
 		if      (dir == LEFT  && S.dir == RIGHT)
 			S.dir = RIGHT;
 		else if (dir == RIGHT && S.dir == LEFT)
@@ -95,7 +94,8 @@ void mv_snake(enum dir dir)
 			S.dir = DOWN;
 		else if (dir == DOWN  && S.dir == UP)
 			S.dir = UP;
-	}
+		else
+			S.dir = dir;

 	switch(S.dir) {
 	case UP   : --y; break;
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by an overly restrictive condition that prevented the snake from changing direction when its length was greater than 1. This restriction led to unintended behavior in the game, as the snake could not adjust its direction properly, resulting in a gameplay issue.

        Commit message:
        fix error introduced by 315a64b1bd6  

        Patch:

 void mv_snake(enum dir dir)
 {
 	int y = S.y[S.ihead];
 	int x = S.x[S.ihead];

 	/* prevent movement inside oneself */
-	if (S.len > 1) {
 		if      (dir == LEFT  && S.dir == RIGHT)
 			S.dir = RIGHT;
 		else if (dir == RIGHT && S.dir == LEFT)
 			S.dir = LEFT;
 		else if (dir == UP    && S.dir == DOWN)
 			S.dir = DOWN;
 		else if (dir == DOWN  && S.dir == UP)
 			S.dir = UP;
-	}
+		else
+			S.dir = dir;

 	switch(S.dir) {
 	case UP   : --y; break;
 	case LEFT : --x; break;
 	case DOWN : ++y; break;
 	case RIGHT: ++x; break;
 	}

 	++S.ihead;
 	S.ihead = rel_ind(0);
 	S.y[S.ihead] = y;
 	S.x[S.ihead] = x;
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>

